class WriteAheadCache:
    def __init__(self, log, cache, store):
        self.log = log      # sequential durable file, supports append + fsync
        self.cache = cache  # fast lookup, lossy on crash
        self.store = store  # backing DB, updated lazily
        self.seq = 0

    def put(self, key, value):
        self.seq += 1
        rec = (self.seq, "PUT", key, value)
        self.log.append(rec)   # 1. intent first, in memory
        self.log.fsync()       # 2. commit point: stable before visible
        self.cache.set(key, (value, self.seq))  # 3. now mutate derived state
        return self.seq

    def recover(self, watermark):
        # Redo only committed prefix; truncate torn tail.
        for seq, op, key, value in self.log.scan_from(watermark):
            if not self.log.is_committed(seq):
                self.log.truncate_from(seq)
                break
            if op == "PUT":
                cur = self.cache.get(key)
                if cur is None or cur[1] < seq:
                    self.cache.set(key, (value, seq))  # idempotent redo
